-- D13 L3: 对与 A001 相交且正常或告警的燃气设备分别建立 300 米缓冲区，合并重叠后裁剪到 A001，求覆盖面积（平方米）以及占 A001 面积的百分比。边界设备计入。
-- 独立只读基准；EPSG:3857、quad_segs=8；不调用工具或执行器。
-- 包含边界设备；先合并再量测；分母是整个 A001；百分比而非 0～1 小数。
WITH a AS (SELECT geom FROM gis_lab.construction_areas WHERE code='A001'), selected AS (SELECT d.geom FROM gis_lab.gas_devices d CROSS JOIN a WHERE d.status IN ('正常','告警') AND ST_Intersects(d.geom,a.geom)), buffered AS (SELECT ST_Buffer(geom,300,'quad_segs=8') AS geom FROM selected), merged AS (SELECT ST_UnaryUnion(ST_Collect(geom)) AS geom FROM buffered), covered AS (SELECT ST_Intersection(m.geom,a.geom) AS geom FROM merged m CROSS JOIN a), metrics AS (SELECT ST_Area(c.geom) AS covered_area,ST_Area(a.geom) AS total_area,c.geom FROM covered c CROSS JOIN a) SELECT jsonb_build_object('area',jsonb_build_object('value',covered_area,'unit','square_meter','measure','area','measure_srid',3857,'is_empty',ST_IsEmpty(geom)),'coverage_percent',jsonb_build_object('value',covered_area/total_area*100,'unit','percent','numerator',covered_area,'denominator',total_area)) AS answer FROM metrics;
